                if (node.firstChild && node.firstChild.nodeType === Node.CDATA_SECTION_NODE) { return node.firstChild.textContent.trim(); }
                return node.innerHTML.trim();
            };

            const nameStr = get('name');
            const hasPortrait = !!charPortraits[nameStr];

            const portraitSection = hasPortrait ? `
                <div class="portrait-wrapper">
                    <div class="portrait-toggle-btn" onclick="const p = this.nextElementSibling; const img = p.querySelector('img'); if(!img.src) { img.src = img.dataset.src; } p.classList.toggle('show'); this.innerHTML = p.classList.contains('show') ? '收起立绘 ▲' : '查看立绘 ▼';">查看立绘 ▼</div>
                    <div class="large-portrait"><img data-src="${charPortraits[nameStr]}" alt="${nameStr}" style="cursor: zoom-in;" onclick="document.getElementById('modal-image').src=this.src; document.getElementById('image-modal-overlay').style.display='flex';"></div>
                </div>` : '';

            return `
                <div class="info-card" style="border-color: rgba(217, 128, 250, 0.3);">
                    <div class="info-title">
                        <span style="color:var(--rare-text)">第${get('rank')}名：${nameStr}</span>
                        <span style="font-size:0.8em; color:var(--text-dim)">${get('title')}</span>
                    </div>
                    <div class="info-text">
                        <b>倾世仙姿：</b> <span style="color:#dcdde1">${getHtml('appearance')}</span><br><br>
                        <b>坊间群芳谱：</b> <i style="font-size:0.9em; color:#bbb;">"${getHtml('rumor')}"</i>
                    </div>
                    ${portraitSection}
                </div>`;
        });

        renderList('world_events > event', '#tab-world_events', item => {
            const get = (tag) => item.querySelector(tag)?.textContent.trim() || '';
            const getHtml = (tag) => {
                const node = item.querySelector(tag);
                if (!node) return '';
                if (node.firstChild && node.firstChild.nodeType === Node.CDATA_SECTION_NODE) { return node.firstChild.textContent.trim(); }
                return node.innerHTML.trim();
            };
            return `
                <div class="quest-item" style="border-left-color: var(--accent-blood);">
                    <div class="info-title">
                        <span style="color:var(--accent-blood)">【${get('type')}】 ${get('title')}</span>
                        <span style="font-size:0.8em; color:var(--text-dim)">📍${get('location')}</span>
                    </div>
                    <div class="info-text">
                        ${getHtml('desc')}
                    </div>
                </div>`;
        });

        renderList('messages > message', '#messages-list', item => {
            const get = (tag) => item.querySelector(tag)?.textContent.trim() || '';
            const getHtml = (tag) => {
                const node = item.querySelector(tag);
                if (!node) return '';
                if (node.firstChild && node.firstChild.nodeType === Node.CDATA_SECTION_NODE) { return node.firstChild.textContent.trim(); }
                return node.innerHTML.trim();
            };

            let contentStr = getHtml('content') || getHtml('text') || getHtml('desc');
            if (!contentStr) {
                let tempItem = item.cloneNode(true);
                Array.from(tempItem.children).forEach(child => {
                    const tagName = child.tagName.toLowerCase();
                    if (tagName === 'sender' || tagName === 'time') {
                        tempItem.removeChild(child);
                    }
                });
                contentStr = tempItem.innerHTML.trim();
            }

            const senderName = get('sender') || '未知';

            return `
                <div class="info-card" style="background: linear-gradient(145deg, rgba(20,40,45,0.7), rgba(15,20,30,0.8)); border-color: rgba(77, 166, 255, 0.4);">
                    <div class="info-title" style="color:var(--accent-mana); border-bottom: 1px solid rgba(77, 166, 255, 0.2);">
                        <span>传讯自：${senderName}</span>
                        <span style="font-size:0.8em; color:var(--text-dim)">${get('time') || '未知'}</span>
                    </div>
                    <div class="info-text" style="color: #e0f0ff; letter-spacing: 1px;">
                        「${contentStr || '...'}」
                    </div>
                    <div class="message-reply-container">
                        <input type="text" class="reply-input" placeholder="传讯玉简回复 ${senderName}...">
                        <button class="reply-button" onclick="handleReply(this, '${senderName}')">传讯</button>
                    </div>
                </div>`;
        });
    }
</script>
</body>
</html>
