<!DOCTYPE html>
<html>
<head>
<title>道渊</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
    @import url('https://fonts.googleapis.com/css2?family=Ma+Shan+Zheng&family=Noto+Serif+SC:wght@400;700&display=swap');

    :root {
        --primary-color: #080c14;
        --accent-blue: #4a90e2;
        --accent-blue-glow: #87cefa;
        --accent-red: #e74c3c;
        --accent-red-glow: #ff7675;
        --accent-pink: #ff69b4;
        --accent-pink-glow: #ffb6c1;
        --text-color: #d0e0f0;
        --border-color: #1c3d5e;
        --gold-color: #D4AF37;
        --input-bg: #101520;
        --input-border: #2a3a50;
        --input-focus-border: var(--gold-color);
        --scroll-bg: #1a202c;
        --scroll-thumb: #2c3e50;
    }

    html, body {
        height: 100%;
        margin: 0;
        padding: 0;
        overflow: hidden;
    }

    body {
        background-color: var(--primary-color);
        background-image:
            radial-gradient(circle at 15% 50%, rgba(74, 144, 226, 0.1), transparent 30%),
            radial-gradient(circle at 85% 30%, rgba(212, 175, 55, 0.08), transparent 25%);
        color: var(--text-color);
        font-family: 'Noto Serif SC', serif;
        display: flex;
        justify-content: center;
        align-items: center;
        width: 100%;
        height: 100vh;
        position: relative;
    }

    #background-particles {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        z-index: 0;
        pointer-events: none;
    }

    .particle {
        position: absolute;
        background-color: var(--accent-blue);
        border-radius: 50%;
        opacity: 0;
        animation: rise 25s infinite linear;
        box-shadow: 0 0 8px var(--accent-blue-glow);
    }

    @keyframes rise {
        0% { transform: translateY(100vh) scale(0.4); opacity: 0; }
        10% { opacity: 0.5; }
        90% { opacity: 0.2; }
        100% { transform: translateY(-10vh) scale(1.3); opacity: 0; }
    }

    .screen {
        position: absolute;
        top: 50%;
        left: 50%;
        width: 90%;
        max-width: 800px;
        background: rgba(10, 15, 25, 0.75);
        border: 2px solid var(--border-color);
        box-shadow: 0 0 20px rgba(74, 144, 226, 0.3), inset 0 0 25px rgba(0, 0, 0, 0.8);
        border-radius: 10px;
        backdrop-filter: blur(8px);
        -webkit-backdrop-filter: blur(8px);
        transition: opacity 1s, transform 1s, visibility 1s;
        display: flex;
        flex-direction: column;
        align-items: center;
        padding: 20px;
        z-index: 10;
        visibility: hidden;
        opacity: 0;
        transform: translate(-50%, -50%) scale(0.95);
    }

    .screen.active {
        visibility: visible;
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }

    #start-screen {
        justify-content: center;
        min-height: 80vh;
        max-height: 90vh;
    }

    .title {
        font-family: 'Ma Shan Zheng', cursive;
        font-size: 3.5em;
        color: var(--accent-blue);
        text-shadow: 0 0 8px var(--accent-blue-glow), 0 0 15px #000;
        margin-bottom: 20px;
        letter-spacing: 4px;
        animation: glow 3.5s infinite alternate;
    }

    .warning-text {
        font-style: normal;
        font-size: 1.1em;
        margin: 0 auto 40px;
        color: #a0b0c0;
        max-width: 80%;
        line-height: 1.8;
        text-align: center;
        font-family: 'Noto Serif SC', serif;
    }

    .start-button-container {
        text-align: center;
    }

    .start-button {
        --size: 100px;
        width: var(--size);
        height: var(--size);
        background-color: var(--primary-color);
        border: 3px solid var(--accent-blue);
        border-radius: 50%;
        display: inline-flex;
        justify-content: center;
        align-items: center;
        cursor: pointer;
        position: relative;
        transition: all 0.3s ease;
        box-shadow: 0 0 20px var(--accent-blue-glow);
        animation: pulse 2.5s infinite;
        margin-bottom: 40px;
    }

    .start-button:hover { transform: scale(1.1); box-shadow: 0 0 35px var(--accent-blue-glow); }

    .start-button-text {
        font-family: 'Noto Serif SC', serif;
        font-size: 1.5em;
        color: var(--gold-color);
        text-shadow: 0 0 5px var(--gold-color);
        transition: all 0.3s ease;
    }


    #character-creation-screen {
        max-height: 90vh;
        overflow-y: auto;
    }

    .form-title {
        font-family: 'Ma Shan Zheng', cursive;
        font-size: 2.2em;
        color: var(--gold-color);
        margin-bottom: 20px;
        border-bottom: 1px solid var(--border-color);
        padding-bottom: 10px;
    }

    .presets-container {
        margin-bottom: 20px;
        width: 100%;
        display: flex;
        flex-direction: column;
        align-items: center;
    }

    .presets-container h3 {
        font-size: 1.3em;
        color: #ccc;
        text-align: center;
        margin-bottom: 15px;
        font-family: 'Noto Serif SC', serif;
    }

    .preset-selection {
        display: flex;
        justify-content: center;
        flex-wrap: wrap;
        gap: 15px;
        max-width: 100%;
        min-width: 0;
        overflow-x: auto;
    }

    #fortune-selection-container {
        flex-wrap: wrap;
        justify-content: center;
    }

    .preset-btn {
        background: var(--input-bg);
        border: 1px solid var(--input-border);
        color: var(--text-color);
        padding: 8px 15px;
        font-family: 'Noto Serif SC', serif;
        cursor: pointer;
        transition: all 0.3s ease;
        border-radius: 4px;
        position: relative;
        white-space: nowrap;
    }

    .preset-btn:hover, .preset-btn.selected {
        background: var(--accent-blue);
        border-color: var(--accent-blue-glow);
        color: #fff;
        box-shadow: 0 0 10px rgba(74, 144, 226, 0.5);
    }

    .preset-btn.true-fortune {
        background: linear-gradient(135deg, #2c3e50 0%, #D4AF37 100%);
        border: 1px solid #D4AF37;
        color: #fff;
        text-shadow: 0 0 5px #000;
        box-shadow: 0 0 15px rgba(212, 175, 55, 0.5);
    }


    .preset-btn.ero-fortune {
        background: linear-gradient(135deg, #2c001e 0%, #8b0046 100%);
        border: 1px solid #ff69b4;
        color: #fff;
        text-shadow: 0 0 5px #ff1493;
        box-shadow: 0 0 15px rgba(255, 105, 180, 0.5);
    }
    .preset-btn.ero-fortune:hover, .preset-btn.ero-fortune.selected {
        background: #ff1493;
        border-color: #ffc0cb;
        box-shadow: 0 0 20px rgba(255, 20, 147, 0.8);
    }


    .draw-fortune-btn {
        padding: 10px 20px;
        font-size: 1.1em;
        font-family: 'Ma Shan Zheng', cursive;
        display: block;
        margin: 0 auto;
        width: fit-content;
    }

    .browse-all-btn {
        padding: 10px 22px;
        font-size: 1.05em;
        font-family: 'Ma Shan Zheng', cursive;
        display: block;
        margin: 10px auto 0;
        width: fit-content;
        background: linear-gradient(135deg, rgba(201, 160, 58, 0.2), rgba(201, 160, 58, 0.05));
        border: 1px dashed rgba(201, 160, 58, 0.5);
        color: #c9a03a;
        cursor: pointer;
        transition: all 0.3s;
    }
    .browse-all-btn:hover {
        background: linear-gradient(135deg, rgba(201, 160, 58, 0.4), rgba(201, 160, 58, 0.1));
        border-color: #ffd700;
        color: #ffd700;
        box-shadow: 0 0 15px rgba(201, 160, 58, 0.3);
    }

    #fortune-name-display {
        color: var(--gold-color);
        margin-left: 10px;
        font-family: 'Ma Shan Zheng', cursive;
        font-size: 1.1em;
    }

    .character-form {
        display: grid;
        grid-template-columns: minmax(0, 1fr);
        gap: 15px;
        width: 100%;
        margin-bottom: 30px;
    }

    .form-group {
        display: flex;
        flex-direction: column;
        text-align: left;
    }

    .form-group label {
        margin-bottom: 5px;
        font-weight: bold;
        color: var(--gold-color);
    }

    .form-group input, .form-group select, .form-group textarea {
        background: var(--input-bg);
        border: 1px solid var(--input-border);
        color: var(--text-color);
        padding: 10px;
        border-radius: 4px;
        font-family: 'Noto Serif SC', serif;
        font-size: 1em;
        width: 100%;
        box-sizing: border-box;
    }

    .form-group input:focus, .form-group select:focus, .form-group textarea:focus {
        outline: none;
        border-color: var(--input-focus-border);
        box-shadow: 0 0 8px rgba(212, 175, 55, 0.5);
    }

    .form-group textarea {
        min-height: 60px;
        resize: vertical;
    }

    .divider-title {
        font-family: 'Ma Shan Zheng', cursive;
        font-size: 1.5em;
        color: var(--gold-color);
        margin-top: 25px;
        margin-bottom: 15px;
        width: 100%;
        text-align: center;
        border-top: 1px solid var(--border-color);
        padding-top: 20px;
    }

    .final-start-button {
        background: var(--accent-blue);
        border: 1px solid var(--accent-blue-glow);
        color: #fff;
        padding: 12px 25px;
        font-family: 'Ma Shan Zheng', cursive;
        font-size: 1.8em;
        cursor: pointer;
        transition: all 0.3s ease;
        border-radius: 5px;
        box-shadow: 0 0 15px rgba(74, 144, 226, 0.7);
    }

    .final-start-button:hover {
        background: var(--accent-blue-glow);
        color: var(--primary-color);
        transform: scale(1.05);
    }

    .gacha-display {
        background: rgba(0, 0, 0, 0.3);
        border: 1px dashed var(--accent-blue);
        padding: 10px;
        margin-top: 5px;
        border-radius: 4px;
        text-align: center;
        font-family: 'Ma Shan Zheng', cursive;
        font-size: 1.2em;
        color: var(--accent-blue-glow);
        min-height: 40px;
        display: flex;
        justify-content: center;
        align-items: center;
    }

    .gacha-display.heaven { color: #ffd700; text-shadow: 0 0 10px #ffd700; border-color: #ffd700; }
    .gacha-display.earth { color: #c0392b; text-shadow: 0 0 8px #c0392b; }
    .gacha-display.profound { color: #9b59b6; }
    .gacha-display.yellow { color: #2ecc71; }
    .gacha-display.waste { color: #7f8c8d; }

    .cheat-toggle-container {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: center;
        margin-bottom: 15px;
        width: 100%;
        gap: 12px;
        padding: 12px 10px;
        background: rgba(20, 20, 30, 0.5);
        border: 1px solid rgba(255, 255, 255, 0.06);
        border-radius: 12px;
    }

    .toggle-group {
        display: flex;
        align-items: center;
        gap: 6px;
        padding: 5px 12px;
        border-radius: 20px;
        background: rgba(0, 0, 0, 0.25);
        transition: background 0.2s, box-shadow 0.2s;
    }
    .toggle-group:hover {
        background: rgba(255, 255, 255, 0.03);
        box-shadow: 0 0 8px rgba(255, 255, 255, 0.04);
    }

    .toggle-divider {
        width: 1px;
        height: 18px;
        background: rgba(255, 255, 255, 0.08);
    }

    .cheat-toggle-label {
        color: var(--accent-red);
        font-weight: bold;
        font-family: 'Noto Serif SC', serif;
        font-size: 0.95em;
        white-space: nowrap;
        line-height: 24px;
    }

    .ero-toggle-label {
        color: var(--accent-pink);
        font-weight: bold;
        font-family: 'Ma Shan Zheng', cursive;
        font-size: 1em;
        text-shadow: 0 0 5px rgba(255, 105, 180, 0.4);
        white-space: nowrap;
        line-height: 24px;
    }


    .custom-toggle-label {
        color: #c9a03a;
        font-weight: bold;
        font-family: 'Ma Shan Zheng', cursive;
        font-size: 0.95em;
        text-shadow: 0 0 4px rgba(201, 160, 58, 0.4);
        white-space: nowrap;
        line-height: 24px;
    }


    .switch {
        position: relative;
        display: inline-block;
        width: 50px;
        height: 24px;
    }

    .switch input {
        opacity: 0;
        width: 0;
        height: 0;
    }

    .slider {
        position: absolute;
        cursor: pointer;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: #ccc;
        -webkit-transition: .4s;
        transition: .4s;
        border-radius: 24px;
    }

    .slider:before {
        position: absolute;
        content: "";
        height: 16px;
        width: 16px;
        left: 4px;
        bottom: 4px;
        background-color: white;
        -webkit-transition: .4s;
        transition: .4s;
        border-radius: 50%;
    }

    .cheat-switch input:checked + .slider {
        background-color: var(--accent-red);
    }
    .cheat-switch input:focus + .slider {
        box-shadow: 0 0 1px var(--accent-red);
    }

    .ero-switch input:checked + .slider {
        background-color: var(--accent-pink);
    }
    .ero-switch input:focus + .slider {
        box-shadow: 0 0 1px var(--accent-pink);
    }


    .custom-switch input:checked + .slider {
        background-color: #c9a03a;
    }
    .custom-switch input:focus + .slider {
        box-shadow: 0 0 1px #c9a03a;
    }

