        border-bottom: 1px solid rgba(212,175,55,0.15);
    }
    .daoyuan-letter-header h2 {
        margin: 0; font-size: 18px; color: #D4AF37;
        font-family: 'Ma Shan Zheng', cursive;
        letter-spacing: 3px; font-weight: 400;
    }
    .daoyuan-letter-body {
