    .daoyuan-letter-body h3 { color: #D4AF37; font-size: 16px; margin: 14px 0 6px; letter-spacing: 1px; }
    .daoyuan-letter-body h3:first-of-type { margin-top: 0; }
    .daoyuan-letter-body p { margin: 6px 0; font-size: 14px; }
    .daoyuan-letter-body em { font-style: normal; color: #D4AF37; font-weight: 600; }
    /* 统一标注 */
    .dl-red { color: #e74c3c; font-weight: 700; }
    .dl-gold { color: #D4AF37; font-weight: 600; }
    .dl-big { font-size: 15px; font-weight: 600; }
    .dl-muted { color: #7a8a9a; }
    .dl-signoff { text-align: right; color: #D4AF37; margin-top: 14px !important; letter-spacing: 1px; }
    .dl-portrait { text-align: center; margin: 16px 0 4px; }
    .dl-portrait img { max-width: 280px; max-height: 360px; border-radius: 8px; border: 1px solid rgba(212,175,55,0.3); }
    .dl-link { color: #D4AF37; text-decoration: underline; text-underline-offset: 2px; word-break: break-all; }
    .dl-link:hover { color: #e0bc50; }
    .daoyuan-letter-footer {
        padding: 12px 20px 16px; flex-shrink: 0; text-align: center;
        border-top: 1px solid rgba(212,175,55,0.1);
    }
    .daoyuan-letter-btn {
        padding: 10px 36px; border-radius: 8px; font-size: 14px;
        font-weight: 700; letter-spacing: 1px; font-family: inherit;
        border: none; transition: all 0.3s;
        color: #666; background: #1a1f2a; pointer-events: none;
    }
    .daoyuan-letter-btn.ready {
        color: #080c14; pointer-events: auto; cursor: pointer;
        background: linear-gradient(160deg, #D4AF37, #b8941f);
        box-shadow: 0 4px 20px rgba(212,175,55,0.3);
    }
    .daoyuan-letter-btn.ready:hover {
        background: linear-gradient(160deg, #e0bc50, #c9a52a);
        box-shadow: 0 6px 24px rgba(212,175,55,0.45);
