        .daoyuan-letter-header h2 { font-size: 16px; }
        .daoyuan-letter-btn { width: 100%; padding: 12px; font-size: 14px; }
    }

    .entry-tooltip {
        position: fixed;
        z-index: 99999;
        background: rgba(10, 15, 25, 0.97);
        border: 1px solid var(--gold-color);
        border-radius: 6px;
        padding: 8px 12px;
        max-width: min(280px, calc(100vw - 20px));
