    /* 新增返回按钮样式 */
    .back-btn {
        position: absolute;
        top: 15px;
        left: 10px;
        background: transparent;
        border: 1px solid var(--border-color);
        color: var(--text-color);
        padding: 3px 10px;
        font-size: 0.9em;
        font-family: 'Noto Serif SC', serif;
        cursor: pointer;
        border-radius: 4px;
        transition: all 0.3s ease;
