    /* 自定义气运多项添加 */
    .cf-priority-hint { font-size: 12px; color: #8a7a5a; margin: 2px 0 10px; text-align: center; }
    .cf-entry { background: var(--input-bg); border: 1px solid var(--input-border); border-radius: 6px; padding: 10px; margin-bottom: 8px; position: relative; }
    .cf-entry-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; }
    .cf-entry-index { font-size: 12px; color: var(--gold-color); font-weight: 600; }
    .cf-delete-btn { background: none; border: 1px solid rgba(231,76,60,0.4); color: #e74c3c; cursor: pointer; border-radius: 4px; font-size: 14px; padding: 2px 8px; line-height: 1; transition: all 0.2s; }
