    .cf-entry input, .cf-entry textarea { width: 100%; box-sizing: border-box; background: #0a0f1a; border: 1px solid #1e2d40; color: var(--text-color); padding: 8px; border-radius: 4px; font-family: inherit; font-size: 13px; margin-bottom: 5px; resize: vertical; }
    .cf-entry textarea { min-height: 48px; }
    .cf-entry input:focus, .cf-entry textarea:focus { outline: none; border-color: var(--input-focus-border); }
    .cf-add-btn { width: 100%; background: transparent; border: 1px dashed rgba(212,175,55,0.3); color: var(--gold-color); padding: 8px; border-radius: 4px; cursor: pointer; font-family: inherit; font-size: 13px; transition: all 0.2s; }
    .cf-add-btn:hover { border-color: var(--gold-color); background: rgba(212,175,55,0.06); }
</style>
