<body>
    <!-- 新增音乐播放器及开关 -->
    <audio id="bgm" loop>
        <source src="https://thumbsnap.com/i/h3oZPwfR.mp4" type="audio/mp4">
    </audio>
    <div id="music-toggle" class="music-btn" title="音乐开关">🔊</div>

    <div id="background-particles"></div>
    <div class="screen active" id="start-screen">
        <h1 class="title">道渊</h1>
        <div class="start-button-container">
            <p class="warning-text" id="initial-warning">“大道三千，殊途同归。然天道无情，以万物为刍狗。汝，欲踏此登仙之路，与天地争一线生机否？”</p>
            <div class="start-button" id="start-button">
                <span class="start-button-text">是</span>
            </div>
        </div>
    </div>

    <div class="screen" id="character-creation-screen">
        <button type="button" id="back-to-mode-btn" class="back-btn">返回</button>

        <h2 class="form-title">重塑仙缘</h2>

        <!-- 新增：存档管理面板 (已折叠优化) -->
        <div class="archive-section">
            <h3 id="archive-toggle-title" style="cursor: pointer; color: var(--gold-color); margin-top: 0; margin-bottom: 5px; font-family: 'Ma Shan Zheng', cursive; font-size: 1.3em; display: flex; justify-content: space-between; align-items: center; user-select: none;">
                <span>仙途玉简 (存档管理)</span>
