                    <input type="file" id="import-file" accept=".json" style="display: none;">
                    <button type="button" id="btn-import-archive" class="preset-btn" style="font-size: 0.9em; padding: 5px 10px;">导入 JSON</button>
                </div>
            </div>
        </div>

        <div class="character-form">
